231	    private static int free(MemoryRegionCache<?>[] caches, boolean finalizer) {
232	        if (caches == null) {
233	            return 0;
234	        }
235	
236	        int numFreed = 0;
237	        for (MemoryRegionCache<?> c: caches) {
238	            numFreed += free(c, finalizer);
239	        }
240	        return numFreed;
241	    }
